// Private coverage is generated by an administrator, never downloaded by ordinary clients.
const ACCESS_GRID_STEP=.001,ACCESS_RADIUS_METERS=3000;
function accessCellFor(lat,lon){return Math.floor((lat+90)/ACCESS_GRID_STEP)+'_'+Math.floor((lon+180)/ACCESS_GRID_STEP)}
function accessDistance(a,b){const r=Math.PI/180,dlat=(b[0]-a[0])*r,dlon=(b[1]-a[1])*r,v=Math.sin(dlat/2)**2+Math.cos(a[0]*r)*Math.cos(b[0]*r)*Math.sin(dlon/2)**2;return 6371000*2*Math.asin(Math.sqrt(Math.min(1,v)))}
function accessAnchors(paths){const points=[],seen=new Set();for(const path of paths){if(!Array.isArray(path))continue;for(let i=0;i<path.length;i++){const p=path[i];if(!Array.isArray(p)||!Number.isFinite(p[0])||!Number.isFinite(p[1]))continue;const prev=path[Math.max(0,i-1)],n=i?Math.max(1,Math.ceil(accessDistance(prev,p)/100)):1;for(let j=i?1:0;j<=n;j++){const t=i?j/n:0,q=i?[prev[0]+t*(p[0]-prev[0]),prev[1]+t*(p[1]-prev[1])]:p;const key=q.map(x=>Math.round(x*100000)).join(',');if(!seen.has(key)){seen.add(key);points.push(q)}}}}return points}
function buildAccessCells(paths){
 const cells={},anchors=accessAnchors(paths),step=ACCESS_GRID_STEP;
 for(const p of anchors){const latRadius=ACCESS_RADIUS_METERS/110500,lonRadius=latRadius/Math.max(.1,Math.cos(p[0]*Math.PI/180));
 for(let row=Math.floor((p[0]-latRadius+90)/step);row<=Math.floor((p[0]+latRadius+90)/step);row++)for(let col=Math.floor((p[1]-lonRadius+180)/step);col<=Math.floor((p[1]+lonRadius+180)/step);col++){
  const key=row+'_'+col;if(cells[key])continue;
  const south=Number((row*step-90).toFixed(6)),west=Number((col*step-180).toFixed(6)),north=Number((south+step).toFixed(6)),east=Number((west+step).toFixed(6));
  const corners=[[south,west],[south,east],[north,west],[north,east]];
  // Every point in an accepted cell stays within 3 km of a sampled point on a road.
  if(corners.every(q=>accessDistance(p,q)<=ACCESS_RADIUS_METERS-2))cells[key]={south,north,west,east};
 }
 }
 return cells;
}
if(typeof module!=='undefined')module.exports={accessCellFor,accessDistance,accessAnchors,buildAccessCells};
